import * as THREE from 'three';
import { createScene } from './data/object.js';
import * as fs from 'fs';

// Create the scene
const root = createScene();

// Rotation matrix for converting from Three.js Y-up to Blender Z-up
// Apply -90 degrees rotation around X axis
const rotationMatrix = new THREE.Matrix4();
rotationMatrix.makeRotationX(-Math.PI / 2);

// Collect all vertices and faces
const allVertices = [];
const allFaces = [];
let vertexOffset = 0;

// Helper function to extract geometry from BufferGeometry
function extractGeometry(geometry, worldMatrix) {
  const position = geometry.getAttribute('position');
  const index = geometry.getIndex();

  if (!position) return { vertices: [], faces: [] };

  const vertices = [];
  const faces = [];

  // Combine world matrix with the rotation to Blender space
  const finalMatrix = new THREE.Matrix4();
  finalMatrix.multiplyMatrices(rotationMatrix, worldMatrix);

  // Extract and transform vertices
  const vertex = new THREE.Vector3();
  for (let i = 0; i < position.count; i++) {
    vertex.set(position.getX(i), position.getY(i), position.getZ(i));
    vertex.applyMatrix4(finalMatrix);
    vertices.push({ x: vertex.x, y: vertex.y, z: vertex.z });
  }

  // Extract faces
  if (index) {
    // Indexed geometry
    for (let i = 0; i < index.count; i += 3) {
      faces.push({
        a: index.getX(i) + 1,     // OBJ is 1-indexed
        b: index.getX(i + 1) + 1,
        c: index.getX(i + 2) + 1
      });
    }
  } else {
    // Non-indexed geometry
    for (let i = 0; i < position.count; i += 3) {
      faces.push({
        a: i + 1,
        b: i + 2,
        c: i + 3
      });
    }
  }

  return { vertices, faces };
}

// Traverse the scene and collect all meshes
function traverseAndCollect(object) {
  // Update world matrix
  object.updateMatrixWorld(true);

  if (object.isMesh) {
    let geometry = object.geometry;

    if (object.isInstancedMesh) {
      // Handle InstancedMesh - extract each instance
      const instanceMatrix = new THREE.Matrix4();
      for (let i = 0; i < object.count; i++) {
        object.getMatrixAt(i, instanceMatrix);

        // Combine instance matrix with world matrix
        const combinedMatrix = new THREE.Matrix4();
        combinedMatrix.multiplyMatrices(object.matrixWorld, instanceMatrix);

        const { vertices, faces } = extractGeometry(geometry, combinedMatrix);

        // Add vertices
        allVertices.push(...vertices);

        // Add faces with offset
        for (const face of faces) {
          allFaces.push({
            a: face.a + vertexOffset,
            b: face.b + vertexOffset,
            c: face.c + vertexOffset
          });
        }

        vertexOffset += vertices.length;
      }
    } else {
      // Regular mesh
      const { vertices, faces } = extractGeometry(geometry, object.matrixWorld);

      // Add vertices
      allVertices.push(...vertices);

      // Add faces with offset
      for (const face of faces) {
        allFaces.push({
          a: face.a + vertexOffset,
          b: face.b + vertexOffset,
          c: face.c + vertexOffset
        });
      }

      vertexOffset += vertices.length;
    }
  }

  // Recursively process children
  for (const child of object.children) {
    traverseAndCollect(child);
  }
}

// Collect all geometry
traverseAndCollect(root);

// Generate OBJ content
let objContent = '# Exported from Three.js\n';
objContent += `# Vertices: ${allVertices.length}\n`;
objContent += `# Faces: ${allFaces.length}\n\n`;

// Write vertices
for (const v of allVertices) {
  objContent += `v ${v.x.toFixed(6)} ${v.y.toFixed(6)} ${v.z.toFixed(6)}\n`;
}

objContent += '\n';

// Write faces
for (const f of allFaces) {
  objContent += `f ${f.a} ${f.b} ${f.c}\n`;
}

// Write to file
fs.writeFileSync('/root/output/object.obj', objContent);

console.log('OBJ file exported successfully to /root/output/object.obj');
console.log(`Total vertices: ${allVertices.length}`);
console.log(`Total faces: ${allFaces.length}`);

